	@Test
	void forkAdmissionDemotesMandatoryBackingAndPreservesItsSingleBuild() throws Exception {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		long limit = 64L << 10;
		var manager = LmdbQueryMemoryManager.createForTesting(limit, limit);
		AtomicInteger builds = new AtomicInteger(), demotions = new AtomicInteger(), closes = new AtomicInteger();
		try {
			LmdbNativeHashJoin.queryMemoryOverride = manager;
			try (var context = new NativeExecutionContext();
					var channel = context.optionalTelemetry(new Object(), target())) {
				var registry = context.optionalMaterializations();
				var ledger = context.memoryLedger();
				var resident = ledger.reserve(4096L, null);
				assertThat(resident).isNotNull();
				OptionalMaterialization.Demotable backing = new OptionalMaterialization.Demotable() {
					private boolean spilled;

					@Override
					public boolean spilled() {
						return spilled;
					}

					@Override
					public boolean demote() {
						assertThat(Thread.holdsLock(manager)).isFalse();
						assertThat(Thread.holdsLock(context.optionalTelemetryRoot())).isFalse();
						assertThat(Thread.holdsLock(channel)).isFalse();
						resident.close();
						spilled = true;
						demotions.incrementAndGet();
						return true;
					}

					@Override
					public void close() {
						resident.close();
						closes.incrementAndGet();
					}
				};
				Object operator = new Object();
				OptionalMaterialization.Factory<OptionalMaterialization.Demotable> producer = () -> {
					builds.incrementAndGet();
					return backing;
				};
				try (var first = registry.acquire(registry.root(), operator, 32L, () -> "mandatory", false,
						context.cancellation(), producer, channel)) {
					assertThat(first.value()).isSameAs(backing);
				}
				try (var pressure = ledger.reserve(limit - manager.usedBytes() - 256L, null);
						var fork = channel.fork()) {
					assertThat(pressure).isNotNull();
					assertThat(backing.spilled()).isTrue();
					assertThat(demotions).hasValue(1);
					assertThat(closes).hasValue(0);
					assertThat(registry.metrics().evictions()).isZero();
					try (var replay = registry.acquire(registry.root(), operator, 32L, () -> "mandatory", false,
							context.cancellation(), producer, channel)) {
						assertThat(replay.value()).isSameAs(backing);
					}
					assertThat(builds).hasValue(1);
				}
			}
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
		assertThat(closes).hasValue(1);
		assertThat(manager.usedBytes()).isZero();
	}

